WOLFSSL_SESSION* ClientSessionToSession(const WOLFSSL_SESSION* session)
{
    SessionRow* sessRow = NULL;
    WOLFSSL_SESSION* ret;

    ret = ClientSessionToSessionRdLocked(session, &sessRow);
    if (sessRow != NULL) {
        SESSION_ROW_UNLOCK(sessRow);
    }

    return ret;
}

